package com.sxw.sxwaiagent.web.controller;
import com.sxw.sxwaiagent.attachment.AttachmentService; import com.sxw.sxwaiagent.auth.AuthenticatedUser; import com.sxw.sxwaiagent.common.api.Result; import com.sxw.sxwaiagent.conversation.ConversationService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/conversations/{conversationId}/attachments") public class AttachmentController { private final AttachmentService s; private final ConversationService c; public AttachmentController(AttachmentService s,ConversationService c){this.s=s;this.c=c;} private long u(Authentication a){return ((AuthenticatedUser)a.getPrincipal()).userId();} @PostMapping public Result<Map<String,Object>> upload(Authentication a,@PathVariable String conversationId,@RequestParam MultipartFile file)throws Exception{c.get(u(a),conversationId);return Result.ok(s.upload(u(a),conversationId,file));} @GetMapping public Result<List<Map<String,Object>>> list(Authentication a,@PathVariable String conversationId){c.get(u(a),conversationId);return Result.ok(s.list(u(a),conversationId));} @DeleteMapping("/{attachmentId}") public Result<Void> delete(Authentication a,@PathVariable String conversationId,@PathVariable String attachmentId)throws Exception{c.get(u(a),conversationId);s.delete(u(a),conversationId,attachmentId);return Result.ok(null);}}
